import java.util.*;

class SparseVector {
  private final Map<Integer, Integer> values = new HashMap<>();

  SparseVector(int[] nums) {
    for (int i = 0; i < nums.length; i++) if (nums[i] != 0) values.put(i, nums[i]);
  }

  public int dotProduct(SparseVector vec) {
    Map<Integer, Integer> small = values.size() <= vec.values.size() ? values : vec.values;
    Map<Integer, Integer> large = small == values ? vec.values : values;
    int sum = 0;
    for (Map.Entry<Integer, Integer> e : small.entrySet()) sum += e.getValue() * large.getOrDefault(e.getKey(), 0);
    return sum;
  }
}
